const raw = String(query || '').trim();
const toInt = ip => {
  const p = ip.split('.').map(Number);
  if (p.length !== 4 || p.some(x => !Number.isInteger(x) || x < 0 || x > 255)) throw new Error('Adresse IPv4 invalide : ' + ip);
  return ((p[0] << 24) >>> 0) + (p[1] << 16) + (p[2] << 8) + p[3];
};
const toIp = n => [n >>> 24, (n >>> 16) & 255, (n >>> 8) & 255, n & 255].join('.');
const maskOf = pfx => (pfx === 0 ? 0 : (0xFFFFFFFF << (32 - pfx)) >>> 0);
const prefixFromMask = m => {
  const n = toInt(m);
  const pfx = n.toString(2).replace(/0+$/, '').length;
  if (maskOf(pfx) !== n || /0/.test(n.toString(2).padStart(32, '0').slice(0, pfx))) throw new Error('Masque invalide : ' + m);
  return pfx;
};
const kind = n => {
  const r = (a, b) => (n >>> 0) >= toInt(a) && (n >>> 0) <= toInt(b);
  if (r('10.0.0.0', '10.255.255.255') || r('172.16.0.0', '172.31.255.255') || r('192.168.0.0', '192.168.255.255')) return 'Privée (RFC 1918)';
  if (r('127.0.0.0', '127.255.255.255')) return 'Loopback';
  if (r('169.254.0.0', '169.254.255.255')) return 'Link-local (APIPA)';
  if (r('100.64.0.0', '100.127.255.255')) return 'CGNAT (RFC 6598)';
  if (r('224.0.0.0', '239.255.255.255')) return 'Multicast';
  return 'Publique';
};
const info = (net, pfx) => {
  const m = maskOf(pfx), n = (net & m) >>> 0, b = (n | (~m >>> 0)) >>> 0;
  const total = 2 ** (32 - pfx);
  const hosts = pfx >= 31 ? (pfx === 31 ? 2 : 1) : total - 2;
  const first = pfx >= 31 ? n : n + 1, last = pfx >= 31 ? b : b - 1;
  return { n, b, m, total, hosts, first, last, pfx };
};
const line = i => `${toIp(i.n)}/${i.pfx}  hôtes ${toIp(i.first)} - ${toIp(i.last)}  broadcast ${toIp(i.b)}  (${i.hosts} hôtes)`;

const m = raw.match(/^(\d+\.\d+\.\d+\.\d+)\s*(?:\/\s*(\d{1,2})|\s+(\d+\.\d+\.\d+\.\d+))?(.*)$/);
if (!m) return 'Format non reconnu. Exemples : 192.168.1.10/24 ; 10.0.0.5 255.255.255.0 ; 192.168.1.0/24 split 4 ; 10.0.0.0/24 hosts 50,20,10';
const ip = toInt(m[1]);
const pfx = m[2] !== undefined ? Number(m[2]) : m[3] ? prefixFromMask(m[3]) : 24;
if (pfx < 0 || pfx > 32) return 'Préfixe invalide (0 à 32).';
const base = info(ip, pfx);
const out = [
  `Adresse saisie : ${m[1]}`,
  `Réseau : ${toIp(base.n)}/${pfx}`,
  `Masque : ${toIp(base.m)}  | Wildcard : ${toIp(~base.m >>> 0)}`,
  `Broadcast : ${toIp(base.b)}`,
  `Plage d'hôtes : ${toIp(base.first)} - ${toIp(base.last)}`,
  `Hôtes utilisables : ${base.hosts}  | Adresses totales : ${base.total}`,
  `Type : ${kind(base.n)}`,
];
const rest = (m[4] || '').trim().toLowerCase();
const sp = rest.match(/^split\s+(\d+)$/);
const hs = rest.match(/^hosts\s+([\d,\s]+)$/);
if (sp) {
  const k = Number(sp[1]);
  const add = Math.ceil(Math.log2(k));
  const np = pfx + add;
  if (np > 32) return out.join('\n') + '\nDécoupage impossible : trop de sous-réseaux.';
  out.push('', `Découpage en ${2 ** add} sous-réseaux /${np} :`);
  for (let i = 0; i < 2 ** add && i < 256; i++) out.push(`  ${i + 1}. ` + line(info(base.n + i * 2 ** (32 - np), np)));
} else if (hs) {
  const needs = hs[1].split(',').map(s => Number(s.trim())).filter(x => x > 0).sort((a, b) => b - a);
  let cur = base.n;
  out.push('', 'Découpage VLSM (du plus grand au plus petit) :');
  for (const h of needs) {
    const np = 32 - Math.ceil(Math.log2(h + 2));
    const size = 2 ** (32 - np);
    cur = Math.ceil(cur / size) * size;
    if (cur + size - 1 > base.b) { out.push(`  ${h} hôtes : ESPACE INSUFFISANT dans ${toIp(base.n)}/${pfx}`); break; }
    out.push(`  besoin ${h} -> ` + line(info(cur, np)));
    cur += size;
  }
}
return out.join('\n');
